import { expect, it } from "vitest";
import { decodeImage } from "@poe-code/image-ast";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { runConvertCli } from "./index.js";

// Generated by native ImageMagick from transparent 3x1 red-left/blue-right frames.
const clears = "R0lGODlhAwABAPAAAAAAAP8AACH/C05FVFNDQVBFMi4wAwEDAAAh+QQJCAAAACwAAAAAAwABAAACAgxQACH5BAkNAAAALAAAAAADAAEAgAAAAAAA/wICBFIAOw==";
const opaque = "R0lGODlhAwABAPAAAP8AAAAAACH/C05FVFNDQVBFMi4wAwEDAAAh+QQACAAAACwAAAAAAwABAAACAoQLACH5BAANAAAALAAAAAADAAEAgP8AAAAA/wICBFIAOw==";

for (const retained of [false, true]) {
  it.each([
    { name: "clearing", input: clears, coalesce: true, widths: [1, 1], offsets: [0, 2], disposal: 3 },
    { name: "opaque", input: opaque, coalesce: false, widths: [3, 1], offsets: [0, 2], disposal: 1 }
  ])(`matches native optimized $name frames (retained=${retained})`, async ({ input, coalesce, widths, offsets, disposal }) => {
    const bytes = Buffer.from(input, "base64");
    const files = new Map([["in.gif", new Uint8Array(bytes)]]), filesystem = new MemoryFileSystem();
    await filesystem.writeFile("/in.gif", bytes);
    expect(await runConvertCli(["in.gif", ...(coalesce ? ["-coalesce"] : []), "-layers", "Optimize", "out.gif"], retained ? { filesystem, cwd: "/" } : files)).toMatchObject({ exitCode: 0 });
    const output = retained ? await filesystem.readFile("/out.gif") : files.get("out.gif")!;
    for (let page = 0; page < 2; page++) {
      const frame = decodeImage(output, { page, coalesce: false });
      expect(frame).toMatchObject({
        width: widths[page], height: 1, virtualCanvas: { width: 3, height: 1, x: offsets[page], y: 0 }, disposal
      });
      // A GIF may reserve a transparent palette entry without using it in the crop.
      for (let alpha = 3; alpha < frame.data.length; alpha += 4) expect(frame.data[alpha]).toBe(255);
    }
    if (coalesce) {
      // Native removes transparency after cropping and uses red as the canvas background.
      const background = 13 + output[11]! * 3;
      expect([...output.slice(background, background + 3)]).toEqual([255, 0, 0]);
      expect([...decodeImage(output, { page: 0, coalesce: false }).data]).toEqual([255, 0, 0, 255]);
      expect([...decodeImage(output, { page: 1, coalesce: false }).data]).toEqual([0, 0, 255, 255]);
    }
    expect(decodeImage(output, { animated: true })).toMatchObject({ delay: [80, 130], loop: 4 });
  });
}
